try{$s=$post&&preg_match('/\A(?:0|[1-9][0-9]{0,2})\z/D',input($post,'version'))?$segments->forAction($year,(int)input($post,'version')):$segmentCurrent;if($s===null)throw new DomainException($segmentCurrentError);}catch(DomainException|JsonException$error){echo '<p role="alert">'.e($segmentText($error->getMessage())).'</p>';if($post!==[]){$originalInputPost=$post;$originalInputText=$segmentText;$originalInputOpen=true;require __DIR__.'/balance-original-inputs.php';}return;}
$segmentFailedAction=input($post,'action');

