$balance=((new Settings($db,(string)$_SESSION['actor']))->section('tax')['data']['accounting_basis']??'euer')==='balance';
$writer=Permissions::actor($db,(string)$_SESSION['actor'])['finance_access']==='write'&&$balance;
$clearing=null;$clearingError='';
if($balance&&$s['version']>0)try{$clearing=(new BalanceClearings($db,(string)$_SESSION['actor']))->get($year);}catch(DomainException|JsonException $error){$clearingError=$error->getMessage();}
$cleared=$clearing&&($clearing['proof']['cases']??[])&&$clearing['source_current']&&$s['carry_current']&&$clearing['statement']['complete'];
$clearingLink=['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'clearings'=>'1'];
$canRebase=$writer&&(!$s['carry_current']||$segmentFailedAction==='balance-segment-rebase')&&BoardAccess::allowed($db,(string)$_SESSION['actor']);
$writer=$writer&&($s['carry_current']||$post!==[]);
$segmentFields=static function(string$action)use($post,$year,$s):string{$same=input($post,'action')===$action;return csrf().hidden('balance_year',$same?input($post,'balance_year'):(string)$year).hidden('version',$same?input($post,'version'):(string)$s['version']).hidden('segment_journal_sha256',$same?input($post,'segment_journal_sha256'):$s['journal']['closed_sha256']).hidden('action',$action);};
$segmentEvidence=static fn(string$action):string=>input($post,'action')===$action?input($post,'evidence'):'';
$segmentReviewed=static fn(string$action):bool=>input($post,'action')===$action&&input($post,'reviewed')==='1';

$money=static fn(int $c):string=>number_format($c/100,2,',','.');
$inputMoney=static fn(int $c):string=>intdiv($c,100).','.str_pad((string)($c%100),2,'0',STR_PAD_LEFT);
$voucher=input($_GET,'segment_voucher',input($_POST,'segment_voucher'));$lineKey=input($_GET,'segment_line',input($_POST,'segment_line'));
$grouped=[];foreach($sources as $key=>$row)$grouped[$row['voucher']][$key]=$row;
$choice=$grouped[$voucher]??[];$line=$sources[$lineKey]??null;
$openingLocked=$s['carry_forward']!==null;
$canEditVoucher=$writer&&!($openingLocked&&$voucher==='opening');
$canEditLine=$writer&&$line&&!($openingLocked&&$line['voucher']==='opening');
$suggested=BalanceSegmentCalculation::suggest($s['journal'],$units);$suggested=array_diff_key($suggested,$allocation['allocations']);
$back=['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'segments'=>'1'];
if($post!==[])ob_start();
