<?php if($post!==[]){
    $segmentHtml=ob_get_clean();$dom=new DOMDocument();$priorErrors=libxml_use_internal_errors(true);
    try{$dom->loadHTML('<?xml encoding="UTF-8"><div id="original-segment-form">'.$segmentHtml.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);}finally{libxml_clear_errors();libxml_use_internal_errors($priorErrors);}
    $xpath=new DOMXPath($dom);$matches=0;
    foreach(iterator_to_array($xpath->query('//form'))as$formNode){
        if(strtolower($formNode->getAttribute('method'))!=='post')continue;
        $actionNode=$xpath->query('.//input[@name="action"]',$formNode)->item(0);
        if($actionNode!==null&&$actionNode->getAttribute('value')===$segmentFailedAction){$formNode->setAttribute('data-unsaved-changes','');$matches++;continue;}
        $formNode->parentNode->removeChild($formNode);
    }
    echo '<section class="card" role="status"><h2>'.e($segmentText('Formularstand')).'</h2><p>'.e($segmentText('Diese Eingaben gehören zum damals geöffneten Aufteilungsstand. Andere Schreibaufträge werden hier nicht angeboten. Aktuellen Stand getrennt prüfen.')).'</p><a class="btn btn-outline" href="'.e(url($back)).'">'.e($segmentText('Aktuelle Bereichsaufteilung öffnen')).'</a></section>';
    if($matches!==1)echo '<p role="alert">'.e($segmentText('Ursprüngliches Formular nicht mehr verfügbar. Aktuellen Stand getrennt öffnen.')).'</p>';
    $root=$dom->getElementById('original-segment-form');if($root!==null)foreach($root->childNodes as$child)echo $dom->saveHTML($child);
} ?>
